//! Identifiers.

use crate::DocKind;

/// An opaque entity identifier.
///
/// The original treats ids as strings with a type prefix (`req_`, `wrk_`,
/// `env_`) and compares them as strings in most of its code, so this stays a
/// transparent newtype over `String` rather than a typed id per entity. A
/// prefixed id is generated by [`Id::generate`].
#[derive(
    Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
#[serde(transparent)]
pub struct Id(String);

impl Id {
    /// Wraps a raw string without validating its format.
    ///
    /// Ids arrive from files this application did not write, so a strict
    /// constructor would reject data the original accepts. Validation, when it
    /// exists, happens where a value is used.
    #[must_use]
    pub fn new(raw: impl Into<String>) -> Self {
        Self(raw.into())
    }

    /// Wraps an identifier that carries no kind prefix.
    #[must_use]
    pub fn opaque(raw: impl Into<String>) -> Self {
        Self(raw.into())
    }

    /// Generates `${prefix}_${uuid_v4_without_dashes}` for the given kind,
    /// matching the original's id generator.
    #[must_use]
    pub fn generate(kind: DocKind) -> Self {
        Self(format!(
            "{}_{}",
            kind.prefix(),
            uuid::Uuid::new_v4().simple()
        ))
    }

    /// Returns the raw string form.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Returns whether the id starts with the prefix of `kind`.
    ///
    /// This is a hint, not a proof: [`DocKind::CaCertificate`] and
    /// [`DocKind::ClientCertificate`] share the `crt` prefix, and the original
    /// checks folder ids with a bare `fld` prefix that also matches unrelated
    /// strings.
    #[must_use]
    pub fn starts_with_kind(&self, kind: DocKind) -> bool {
        self.0.starts_with(kind.prefix())
    }
}

impl std::fmt::Display for Id {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl From<&str> for Id {
    fn from(value: &str) -> Self {
        Self::new(value)
    }
}

impl From<String> for Id {
    fn from(value: String) -> Self {
        Self::new(value)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_a_prefixed_id() {
        let id = Id::generate(DocKind::Request);
        assert!(id.as_str().starts_with("req_"));
        assert!(id.starts_with_kind(DocKind::Request));
    }

    #[test]
    fn generated_ids_are_unique() {
        assert_ne!(
            Id::generate(DocKind::Workspace),
            Id::generate(DocKind::Workspace)
        );
    }

    #[test]
    fn the_uuid_has_no_dashes() {
        let id = Id::generate(DocKind::Environment);
        let raw = id.as_str().trim_start_matches("env_");
        assert_eq!(raw.len(), 32);
        assert!(!raw.contains('-'));
    }

    #[test]
    fn serializes_transparently() -> Result<(), serde_json::Error> {
        let id = Id::new("wrk_123");
        assert_eq!(serde_json::to_string(&id)?, r#""wrk_123""#);
        let back: Id = serde_json::from_str(r#""wrk_123""#)?;
        assert_eq!(back, id);
        Ok(())
    }
}
